r=[]
r.append(R(7273074,"धीमी आँच पर भुने लहसुन और जड़ी-बूटी वाले टमाटर","मीठे, कैरेमलाइज़ किए हुए टमाटर सैंडविच में या पास्ता के साथ बिल्कुल सही लगते हैं।","2","213 ग्राम",
["6 लहसुन की फांकें, कुचली हुई","1 छोटा चम्मच सूखा ऑरिगैनो","2 चुटकी पिसी काली मिर्च","1 बड़ा चम्मच जैतून का तेल, साथ में बेकिंग ट्रे को चिकना करने के लिए थोड़ा और","4 बड़े वाइन टमाटर (लगभग 500 ग्राम)"],
["ओवन को 150°C/गैस 2 पर पहले से गरम करें। लहसुन, ऑरिगैनो, काली मिर्च और जैतून का तेल मिलाएँ और चम्मच के पिछले हिस्से से सबको एक साथ कुचलें।","टमाटरों को बीच से आधा काटें। फिर टमाटरों के कटे हुए हिस्से को ऊपर करके, हर आधे हिस्से के बीच में कुछ चीरे लगाएँ, ध्यान रखें कि वे छिलके तक आर-पार न हो जाएँ।","लहसुन के मिश्रण को टमाटरों में बाँट दें और धीरे से गूदे में दबाएँ।","हल्के चिकने किए बेकिंग शीट पर रखें और ओवन में 1 घंटे तक बेक करें।"],
["ये टमाटर फ्रिज में दो दिन तक रखे जा सकते हैं और ज़रूरत पड़ने पर दोबारा गरम किए जा सकते हैं।","यह व्यंजन टोस्ट की हुई चियाबाटा ब्रेड पर, या ग्रिल किए हुए मांस या मछली के साथ परोसने पर शानदार लगता है।",FV(1)]))
r.append(R(7274125,"फूलगोभी पुलाव","चावल का एक स्वादिष्ट कम कार्बोहाइड्रेट वाला विकल्प, जिसे धनिये और भुने मेवों की परत के साथ गरम या सलाद की तरह ठंडा खाया जा सकता है।","4","241 ग्राम",
["1 मध्यम फूलगोभी, तैयार करने के बाद 750 ग्राम","2 छोटे चम्मच रेपसीड तेल","4 हरी प्याज़ (स्प्रिंग अनियन), बारीक कटी हुई","1 लहसुन की फांक, कुचली हुई","1 लाल शिमला मिर्च, कटी हुई","2 छोटे चम्मच पिसा जीरा","एक अच्छी चुटकी सफ़ेद मिर्च","75 ग्राम जमे हुए मटर","25 ग्राम सुल्ताना (सुनहरी किशमिश)","1 बड़ा चम्मच धनिया, बारीक कटा हुआ","1 बड़ा चम्मच भुने हुए बादाम के फ्लेक्स"],
["फूलगोभी के डंठल निकालें, मोटे टुकड़ों में तोड़ें और हाथ से कद्दूकस करें या फ़ूड प्रोसेसर में पीस लें।","फूलगोभी को कटोरे में डालें, क्लिंग फ़िल्म से ढकें और फ़िल्म में दो-तीन छेद करें। माइक्रोवेव में तेज़ आँच पर 4-5 मिनट तक पकाएँ। ठंडा होने दें।","ठंडा होने के बाद, फूलगोभी को साफ़ तौलिये पर रखें और अतिरिक्त पानी निकालने के लिए सिंक के ऊपर निचोड़ें।","इस बीच, सॉसपैन में तेल गरम करें और हरी प्याज़, लहसुन और लाल शिमला मिर्च को चलाते हुए 2 मिनट तक भूनें। जीरा और काली मिर्च डालकर अच्छी तरह मिलाएँ, फिर जमे हुए मटर और सुल्ताना डालें और 2 मिनट और पकाएँ।","फूलगोभी मिलाएँ और ऊपर से धनिया और बादाम डालें।"],
["इस पुलाव के अनगिनत रूप हो सकते हैं। आप बाकला, सेलरी, सौंफ़ के कंद या तोरी जैसी दूसरी सब्ज़ियाँ और ताज़ा पुदीना, अजमोद या सोआ जैसी जड़ी-बूटियाँ डाल सकते हैं।","आप अनार या क्रैनबेरी जैसे फल भी डाल सकते हैं।","अगर आपके पास माइक्रोवेव नहीं है, तो चरण 2 में फूलगोभी को 2 मिनट तक भाप में पकाएँ।","फ्रीज़ करने के निर्देश: पिघलाएँ, फिर परोसने के लिए माइक्रोवेव में या चूल्हे पर मध्यम आँच पर गरम करें।",FV(2)]))
r.append(R(7276005,"मल्ड एप्पल जूस","मल्ड वाइन का एक गरमाहट देने वाला, मसालेदार, बिना अल्कोहल वाला विकल्प।","12","171 ग्राम",
["2 संतरे, कटे हुए","2 या 3 दालचीनी की छड़ियाँ","3 सेमी ताज़ा अदरक की जड़, छीली और पतली कटी हुई","2 स्टार ऐनीज़ (चक्र फूल), और परोसने के लिए अतिरिक्त","6 साबुत लौंग, और परोसने के लिए अतिरिक्त","1 लीटर 100% शुद्ध सेब का रस"],
["1 संतरा, 1 दालचीनी की छड़ी, अदरक, स्टार ऐनीज़ और लौंग को एक लीटर उबलते पानी के साथ सॉसपैन में डालें और दस मिनट तक हल्की आँच पर पकाएँ।","सेब का रस डालें और 3-4 मिनट तक हल्के से गरम करें, ध्यान रखें कि उबाल न आए।","छान लें, जग या अलग-अलग गिलासों में डालें और दालचीनी की छड़ियों, संतरे के स्लाइस, लौंग और स्टार ऐनीज़ से सजाएँ।"],
["आप इस रेसिपी को बिना चीनी वाले क्रैनबेरी जूस के साथ बनाकर मौसमी माणिक-लाल पेय बना सकते हैं।",FV(0)]))
r.append(R(7276558,"भुनी शिमला मिर्च और सन-ड्राइड टमाटर क्रॉस्टिनी","शाकाहारी बुफ़े के लिए बिल्कुल सही व्यंजन।","20","29 ग्राम",
["1 मल्टीग्रेन/बीज वाली आधी बैगेट (लगभग 200 ग्राम)","2 छोटे चम्मच जैतून का तेल","1 लाल शिमला मिर्च, चार भागों में कटी हुई","1 लाल प्याज़, 8 फांकों में कटा हुआ","1 गाजर, लंबे टुकड़ों में कटी हुई","1 छोटा चम्मच सूखा ऑरिगैनो","एक छींटा बाल्समिक सिरका","4 सन-ड्राइड टमाटर, बारीक कटे हुए","सजाने के लिए ताज़ी तुलसी"],
["ओवन को 200°C/गैस 6 पर पहले से गरम करें। ब्रेड को 1 सेमी मोटे गोल टुकड़ों में काटें – आपको लगभग 20 चाहिए होंगे।","बेकिंग शीट पर 1 छोटा चम्मच तेल डालें और (किचन पेपर से) समान रूप से फैलाएँ। ब्रेड के स्लाइस बेकिंग शीट पर सजाएँ और ओवन में 7-8 मिनट तक बेक करें। फिर ब्रेड के स्लाइस पलट दें, अगर वे बराबर नहीं पक रहे हों तो उन्हें इधर-उधर करें, और 5 मिनट और बेक करें। वे सुनहरे भूरे और कुरकुरे होने चाहिए।","इस बीच, शिमला मिर्च, लाल प्याज़ और गाजर को दूसरे 1 छोटे चम्मच जैतून के तेल के साथ कटोरे में डालें और अच्छी तरह मिलाएँ। मिश्रण को बेकिंग शीट पर फैलाएँ और 15-20 मिनट तक भूनें।","सब्ज़ियाँ ठंडी हो जाने पर, उन्हें बारीक काटें और फिर ऑरिगैनो, बाल्समिक सिरके और सन-ड्राइड टमाटरों के साथ कटोरे में डालें।","परोसने के लिए, मिश्रण का एक चम्मच हर ब्रेड स्लाइस पर रखें और ताज़ी तुलसी से सजाएँ। (हमने ग्रीक तुलसी इस्तेमाल की, लेकिन अजमोद, चाइव्स या धनिया भी उतने ही अच्छे लगते हैं)। परोसने के बाद, क्रॉस्टिनी 2-3 घंटे तक अच्छी रहेगी, लेकिन फिर टोस्ट नरम होने लगेगा।"],
["लहसुन का ज़्यादा तीव्र स्वाद पाने के लिए, ऊपर से सामग्री डालने से पहले हर क्रॉस्टिनी पर लहसुन की एक फांक रगड़ें।","क्रॉस्टिनी टोस्ट एक दिन पहले बनाकर एयरटाइट डिब्बे में रख लें।",FV(0)]))
r.append(R(7277182,"सौंफ़ रैटाटुइल पर सैल्मन","सैल्मन को भाप में पकाकर रैटाटुइल की परत पर परोसने वाला ग्लूटेन-मुक्त व्यंजन।","1","601 ग्राम",
["1 छोटा चम्मच जैतून का तेल","1 छोटा लाल प्याज़, मोटा कटा हुआ","1 पीली शिमला मिर्च, कटी हुई","1 लहसुन की फांक, कुचली हुई","एक अच्छी चुटकी सूखा ऑरिगैनो","चुटकी भर काली मिर्च","2 ताज़े पके टमाटर, कटे हुए","आधा छोटा सौंफ़ का कंद, पतला कटा हुआ","1 सैल्मन फ़िलेट, 125 ग्राम","2 बड़े चम्मच पानी","परोसने के लिए ताज़ी तुलसी की पत्तियाँ"],
["एक बड़े पैन में मध्यम आँच पर तेल डालें। प्याज़ डालें और 2-3 मिनट तक नरम होने तक चलाएँ।","अब पीली शिमला मिर्च डालें और 3-4 मिनट तक नियमित रूप से चलाएँ।","लहसुन, ऑरिगैनो, मसाला, टमाटर और सौंफ़ का कंद डालें। 2 मिनट और चलाएँ और उबाल आने दें।","सैल्मन को रैटाटुइल के ऊपर रखें, पानी डालें और ढक्कन या फ़ॉइल से ढक दें। 4-5 मिनट तक या सैल्मन के अंदर तक पकने तक हल्की आँच पर पकाएँ।","सैल्मन को निकालें, रैटाटुइल में कुछ फटी हुई ताज़ी तुलसी की पत्तियाँ मिलाएँ और परोसें।"],
["सैल्मन की जगह सी बास या कॉड इस्तेमाल करें।","रैटाटुइल में एक बैंगन डालें।",FV(6)]))
r.append(R(7278452,"चिकन, मशरूम और टैरागन पाई","शकरकंद की सेहतमंद परत वाली, टैरागन के स्वाद से भरी एक मलाईदार पाई।","2","620 ग्राम",
["2 छोटे चम्मच सूरजमुखी का तेल","1 बड़ा प्याज़, बारीक कटा हुआ","2 बड़े लीक, साफ़ किए हुए और कटे हुए","150 ग्राम चेस्टनट मशरूम, कटे हुए","300 मिलीलीटर चिकन या वेजिटेबल स्टॉक","1 बड़ा चम्मच ताज़ा कटा टैरागन","चुटकी भर सफ़ेद मिर्च","1 ढेर वाला छोटा चम्मच कॉर्नफ़्लोर, 25 मिलीलीटर स्किम्ड दूध में मिला हुआ","150 ग्राम ठंडा पका हुआ बिना त्वचा का चिकन, टुकड़ों में कटा हुआ (भूरे और सफ़ेद मांस का मिश्रण)","300 ग्राम शकरकंद, छीली हुई और बहुत पतली कटी हुई"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। पैन में तेल डालें, फिर प्याज़ डालें और 5 मिनट तक भूरा होने तक नियमित रूप से चलाएँ।","लीक और मशरूम डालें, और 3-4 मिनट तक नरम होने तक नियमित रूप से चलाएँ।","स्टॉक, टैरागन और काली मिर्च मिलाएँ और उबाल लाएँ। पैन पर ढक्कन लगाएँ, आँच कम करें और 5 मिनट तक हल्की आँच पर पकाएँ।","कॉर्नफ़्लोर और दूध को मिलाएँ। इसके बाद, स्टॉक को फिर से उबालें और कॉर्नफ़्लोर के मिश्रण को धीरे-धीरे मिलाएँ जब तक कि सॉस गाढ़ा न हो जाए, फिर 2 मिनट और चलाएँ।","अब पके हुए चिकन के टुकड़े मिलाएँ, फिर मिश्रण को ओवन-प्रूफ़ डिश में डालें।","शकरकंद को ऊपर समान रूप से परत में लगाएँ और ओवन में 25-40 मिनट तक हल्का भूरा होने तक बेक करें।"],
[FV(4)]))
r.append(R(7280237,"लाल प्याज़ और लहसुन के साथ करी पालक","एक हल्की करी जिसे आप अपनी पसंद के अनुसार कम या ज़्यादा तीखा बना सकते हैं।","2","217 ग्राम",
["1 x 250 ग्राम का पालक का पैकेट","1 छोटा चम्मच सूरजमुखी का तेल","1 लाल प्याज़, आधा करके पतला कटा हुआ","2 लहसुन की फांकें, पतली कटी हुई","2 छोटे चम्मच करी पेस्ट (हल्का या जितना तीखा आपको पसंद हो)","1 बड़ा चम्मच कम वसा वाला क्रेम फ्रेश"],
["पालक को धोएँ और ढक्कन वाले पैन में डालें, दो-तीन बार चलाते हुए 2-3 मिनट तक पकाएँ (तेल या अतिरिक्त पानी डालने की ज़रूरत नहीं है, धोने के बाद पालक पर चिपका पानी काफ़ी होगा)। छलनी में डालें और अलग रख लें।","इस बीच, पैन में तेल डालें, प्याज़ डालें और 2-3 मिनट तक नरम होने तक पकाएँ।","अब लहसुन डालें और 2 मिनट चलाएँ, फिर करी पेस्ट मिलाएँ।","पालक डालें, 1-2 मिनट अच्छी तरह मिलाएँ, फिर क्रेम फ्रेश मिलाएँ और परोसें।"],
["वीगन संस्करण के लिए क्रेम फ्रेश की जगह सोया-आधारित दही इस्तेमाल करें।","आप झटपट साग आलू बनाने के लिए कुछ उबले हुए, कटे आलू भी मिला सकते हैं।","फ्रीज़ करने के निर्देश: माइक्रोवेव में पिघलाएँ, फिर पूरी तरह भाप निकलने तक गरम होने तक दोबारा गरम करें।",FV(2)]))
r.append(R(7283095,"चना दाल","यह व्यंजन दक्षिण एशियाई व्यंजनों का एक मुख्य हिस्सा है। दालें प्रोटीन, आयरन और अघुलनशील तथा घुलनशील दोनों प्रकार के फ़ाइबर का उत्कृष्ट स्रोत हैं।","4","306 ग्राम",
["225 ग्राम पीली दाल, धोई हुई और 2 घंटे भिगोई हुई","आधा छोटा चम्मच लाल मिर्च पाउडर","2 लहसुन की फांकें, छीली और कटी हुई","एक चौथाई छोटा चम्मच हल्दी","1 छोटा चम्मच जैतून/सूरजमुखी का तेल","1 बड़ा प्याज़, कटा हुआ","1 हरी मिर्च, बारीक कटी हुई","आधा छोटा चम्मच गरम मसाला पाउडर","1 बड़ा चम्मच ताज़ा धनिया, कटा हुआ"],
["दाल को पैन में डालें और 1.2 लीटर पानी से ढकें ताकि पानी दाल से लगभग 4 सेमी ऊपर रहे। लाल मिर्च पाउडर, लहसुन और हल्दी डालें और उबाल लाएँ। ढककर धीमी आँच पर लगभग एक घंटे तक नरम होने तक पकाएँ।","फ्राइंग पैन में तेल गरम करें, कटा हुआ प्याज़ डालें और सुनहरा भूरा होने तक भूनें। सजाने के लिए कुछ तले हुए प्याज़ अलग रख लें। अब हरी मिर्च डालें। इसे दाल के मिश्रण में मिलाएँ, फिर प्याज़, गरम मसाला और धनिये से सजाएँ।"],
["ज़्यादा स्वाद के लिए आप प्याज़ में अतिरिक्त लहसुन डाल सकते हैं। 2-3 फांकें पतली काटें और प्याज़ के साथ कुछ मिनट पकाएँ।","फ्रीज़ करने के निर्देश: माइक्रोवेव में पिघलाएँ, फिर बहुत धीमी आँच पर पूरी तरह भाप निकलने तक गरम होने तक पकाएँ।","अगर आपके पास लहसुन या मिर्च नहीं है, तो आप लाल मिर्च पाउडर और लहसुन के दाने इस्तेमाल कर सकते हैं, बस लेबल देख लें कि उसमें अतिरिक्त नमक न हो।",FV(1)]))
r.append(R(7284915,"माइक्रोवेव मग: चीज़ी चाइव्स और मटर मफ़िन","अंतिम फ़ास्ट फ़ूड, यह चीज़ी व्यंजन पेट भरने वाला, स्वादिष्ट और सिर्फ़ छह मिनट में तैयार है।","1","164 ग्राम",
["1 अंडा, फेंटा हुआ","1 ढेर वाला बड़ा चम्मच सादा कम वसा वाला दही","एक अच्छी चुटकी सफ़ेद मिर्च","10 ग्राम आधी वसा वाला चेडर, कद्दूकस किया हुआ","5 ग्राम पार्मेसन, बारीक कद्दूकस किया हुआ","1 हरी प्याज़ (स्प्रिंग अनियन), बारीक कटी हुई","40 ग्राम जमे हुए मटर, पिघलाए हुए","1 ढेर वाला बड़ा चम्मच साबुत गेहूँ का आटा","एक-तिहाई छोटा चम्मच बेकिंग पाउडर या बेकिंग सोडा","1 ढेर वाला छोटा चम्मच कटी हुई चाइव्स (सजाने के लिए कुछ बचाकर रखें)","आधा छोटा चम्मच सूरजमुखी का तेल","चुटकी भर पेपरिका"],
["एक कटोरे में अंडा, दही, सफ़ेद मिर्च और चीज़ को फेंटें और अच्छी तरह मिलाएँ। हरी प्याज़ और मटर मिलाएँ।","आटा और बेकिंग पाउडर मिलाएँ और अच्छी तरह मिलाएँ। एक मग में हल्का तेल लगाएँ, फिर मिश्रण डालें। पूरी शक्ति (800W) पर 2 मिनट गरम करें, फिर 1 मिनट रखा रहने दें।","परोसने के लिए ऊपर से पेपरिका और कुछ चाइव्स छिड़कें।","इसे सीधे मग से खाया जा सकता है या प्लेट में पलटकर सलाद के साथ परोसा जा सकता है।"],
["अतिरिक्त स्वाद के लिए अजमोद, पुदीना या तुलसी जैसी और ताज़ी जड़ी-बूटियाँ डालें।","आप स्वीटकॉर्न, बारीक कटी सेलरी या शिमला मिर्च जैसी दूसरी सब्ज़ियाँ इस्तेमाल कर सकते हैं।",FV(0)]))
r.append(R(7285911,"परफ़ेक्ट पैनकेक","पैनकेक की एक बेहतरीन रेसिपी – मीठी या नमकीन दोनों तरह की टॉपिंग के साथ बढ़िया लगती है।","8","58 ग्राम",
["100 ग्राम मैदा","1 अंडा, फेंटा हुआ","300 मिलीलीटर स्किम्ड दूध","1 छोटा चम्मच रेपसीड तेल"],
["मैदे को एक कटोरे में छान लें।","फेंटा हुआ अंडा डालें, फिर चिकना घोल बनाने के लिए धीरे-धीरे स्किम्ड दूध को फेंटते हुए मिलाएँ।","30 मिनट से 1 घंटे तक रखा रहने दें।","गरम पैन में हल्का तेल लगाएँ। 2-3 बड़े चम्मच घोल डालें और उसे पैन में पतला फैलाने के लिए हल्के से घुमाएँ। 30-40 सेकंड तक छोड़ दें, किनारों पर परत बन जानी चाहिए और पैनकेक बीच में बुलबुले छोड़ेगा","1-2 मिनट तक पकाएँ, फिर उछालकर या पलटकर दूसरी तरफ़ 1 मिनट तक या सुनहरा होने तक पकाएँ।"],
["पैनकेक को गरम रखने के लिए, बहुत हल्के उबलते पानी वाले सॉसपैन पर एक प्लेट रखें, पैनकेक डालें और दूसरी प्लेट से ढक दें।","पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज में या माइक्रोवेव में पिघलाएँ और पूरी तरह भाप निकलने तक गरम होने तक दोबारा गरम करें।",FV(0)]))
r.append(R(7287673,"कुरकुरा गाजर और सेब का सलाद","एक सरल, स्वादिष्ट सलाद जिसे आप 3 मिनट में झटपट बना सकते हैं।","2","138 ग्राम",
["1 x गाजर (1 मध्यम)","1 x हरा सेब (1 मध्यम)","2 x मध्यम मूली (16 ग्राम)","½ नीबू का रस","2 छोटे चम्मच जैतून का तेल","2 बड़े चम्मच तिल (24 ग्राम) वैकल्पिक"],
["एक गाजर और एक हरे सेब को छीलकर मोटा कद्दूकस करें। परोसने के कटोरे में डालें।","2 मूली को बहुत बारीक काटें। ताज़े नीबू के रस और 2 छोटे चम्मच जैतून के तेल के साथ कटोरे में डालें।","काली मिर्च से अच्छी तरह मसाला डालें और गाजर के साथ अच्छी तरह मिलने तक उछालें।","भुने हुए तिल (वैकल्पिक) छिड़ककर परोसें। कमरे के तापमान पर परोसना सबसे अच्छा है।"],
[FV(1)]))
r.append(R(7288649,"सेवइयों की खीर","शानदार सुगंधित स्वादों वाली एक पारंपरिक एशियाई मिठाई।","6","243 ग्राम",
["125 ग्राम बारीक सेवइयाँ","1.2 लीटर सेमी-स्किम्ड दूध","2 इलायची की फलियाँ","स्वाद अनुसार कृत्रिम स्वीटनर","60 ग्राम पिस्ता, मोटा कटा हुआ"],
["एक पैन में पानी उबालें, सेवइयाँ डालें और 2 मिनट तक हल्की आँच पर पकाएँ।","पानी निकाल दें। वापस पैन में डालें और दूध डालें।","बीच-बीच में चलाते हुए 15-20 मिनट तक हल्की आँच पर पकाएँ, जब तक कि सेवइयाँ और दूध गाढ़े न हो जाएँ।","आँच से उतारें, अपने स्वाद के अनुसार स्वीटनर से मीठा करें और ऊपर से पिस्ता छिड़कें।"],
["आप इस पुडिंग में सेवइयों की जगह मैकरोनी इस्तेमाल कर सकते हैं।","किशमिश, सुल्ताना, प्रून या खुबानी जैसे कुछ सूखे मेवे डालकर देखें।","अतिरिक्त स्वाद के लिए जायफल, दालचीनी या मिक्स्ड स्पाइस की एक अच्छी चुटकी डालें।"]))
r.append(R(7291211,"मसालेदार सेब और किशमिश मूसली बार","सेब, किशमिश और मिले-जुले बीज इसे घर पर बनने वाला बिल्कुल सही नाश्ता बनाते हैं।","16","54 ग्राम",
["2 केले (प्रत्येक छीलने के बाद 100 ग्राम वज़न)","2 सेब, बीच का हिस्सा निकाले हुए और बारीक कटे हुए, लेकिन छिले नहीं (प्रत्येक 125 ग्राम)","175 ग्राम रोल्ड ओट्स","150 मिलीलीटर सेब का रस","40 ग्राम किशमिश","40 ग्राम मिले-जुले बीज, जैसे सूरजमुखी और कद्दू के","1 ढेर वाला छोटा चम्मच पिसी दालचीनी","1 छोटा चम्मच रेपसीड तेल"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। कांटे से केलों को अच्छी तरह मैश करें, फिर थोड़ा फेंटें।","सेब, ओट्स, सेब का रस, किशमिश, बीज और दालचीनी डालें। अच्छी तरह मिलाएँ।","बेकिंग शीट पर तेल लगाएँ और मिश्रण को 2 सेमी की गहराई तक फैलाएँ।","ओवन में 15-20 मिनट तक बेक करें।","ठंडा होने दें, 16 हिस्सों में काटें और परोसें।"],
["आप इस रेसिपी में तिल, भांग के बीज या खसखस, और अलसी के बीज डाल सकते हैं। या आप पहले से मिले हुए बीजों का एक पैकेट खरीद सकते हैं।","कमरे के तापमान पर एयरटाइट डिब्बे में दो दिन तक, या फ्रिज में एक हफ़्ते तक रखें।",FV(0)]))
r.append(R(7293684,"वीगन स्टैक बर्गर","मसालेदार बीन बर्गर जिसके ऊपर रंग-बिरंगी, चारकोल पर भुनी सब्ज़ियाँ हैं, सलाद से भरपूर, और तीखी तिल की सॉस में सराबोर।","4","553 ग्राम",
[("बर्गर के लिए","400 ग्राम का डिब्बा मिली-जुली बीन्स, छानी और मैश की हुई"),("बर्गर के लिए","1 शकरकंद, छीली, उबली और मैश की हुई (250 ग्राम)"),("बर्गर के लिए","1 प्याज़, बारीक कद्दूकस किया हुआ"),("बर्गर के लिए","1 छोटा चम्मच करी पेस्ट"),("बर्गर के लिए","2 लहसुन की फांकें, कुचली हुई"),("बर्गर के लिए","2 छोटे चम्मच रेपसीड तेल, तलने के लिए"),("चारकोल पर भुनी सब्ज़ियाँ","आधा बैंगन, 4 x 4 सेमी के 4 स्लाइस में कटा हुआ"),("चारकोल पर भुनी सब्ज़ियाँ","4 पोर्टोबेलो मशरूम, डंठल निकाले हुए"),("चारकोल पर भुनी सब्ज़ियाँ","1 तोरी, लंबे स्लाइस में कटी हुई"),("चारकोल पर भुनी सब्ज़ियाँ","1 लाल शिमला मिर्च, चार भागों में कटी हुई"),("चारकोल पर भुनी सब्ज़ियाँ","1 पीली शिमला मिर्च, चार भागों में कटी हुई"),("सलाद","8 लिटिल जेम लेट्यूस के पत्ते"),("सलाद","1 बहुत बड़ा टमाटर, कटा हुआ"),("सलाद","1 लाल प्याज़, पतला कटा हुआ"),("सलाद","4 साबुत गेहूँ के बैप्स (बन), आधे कटे और हल्के टोस्ट किए हुए (प्रत्येक 65 ग्राम)"),("सॉस","4 छोटे चम्मच ताहिनी, 1 नीबू के रस और 2 बड़े चम्मच पानी के साथ मिली हुई")],
["बर्गर की सामग्री को (तेल को छोड़कर) एक साथ मिलाएँ, 4 टिक्कियाँ बनाएँ और 20 मिनट के लिए फ्रिज में रखें।","इस बीच, बैंगन, मशरूम, तोरी और","शिमला मिर्च को चारकोल ग्रिल पर या ग्रिल पर भूनें और गरम रखें।","जब सब्ज़ियाँ ग्रिल हो रही हों, तब अपना सलाद गार्निश और ताहिनी सॉस तैयार करें।","नॉन-स्टिक पैन में धीमी-से-मध्यम आँच पर तेल डालें और बर्गर को हर तरफ़ 4-6 मिनट तक सुनहरा भूरा होने और अंदर तक गरम होने तक पकाएँ।","बन को टोस्ट करें, फिर सलाद, बर्गर और चारकोल पर भुनी सब्ज़ियाँ डालें, ऊपर से ताहिनी छिड़कें और सींक से बाँध दें।"],
["इन बर्गरों के लिए ज़्यादातर बीन्स या छोले चलते हैं, इसलिए जो भी आपके पास हो उसका इस्तेमाल करें।",FV(4)]))
